class Solution {
    public long taskSchedulerII(int[] tasks,int space){
        Map<Integer,Long> lastDay=new HashMap<>();
        long day=0;
        for(int task:tasks){
            day++;
            if(lastDay.containsKey(task))day=Math.max(day,lastDay.get(task)+space+1);
            lastDay.put(task,day);
        }
        return day;
    }
}

code.kotlin:
class Solution {
    fun taskSchedulerII(tasks:IntArray,space:Int):Long{
        val lastDay=HashMap<Int,Long>();
        var day=0L;
        for(task in tasks){
            day++;
            lastDay[task]?.let{
                day=maxOf(day,it+space+1)
            };
            lastDay[task]=day
        };
        return day
    }
}

code.cpp:
class Solution {
    public:long long taskSchedulerII(vector<int>& tasks,int space){
        unordered_map<int,long long> lastDay;
        long long day=0;
        for(int task:tasks){
            ++day;
            if(lastDay.count(task))day=max(day,lastDay[task]+space+1);
            lastDay[task]=day;
        }
        return day;
    }
};
